console.log(JSON.stringify(res, null, 2));

const tabId = 118779795;

const sampleProviders = await browserjs(tabId, async () => {
  const items = Array.from(document.querySelectorAll('.ipc-metadata-list-summary-item'));
  const movies = items.slice(0, 30).map(item => {
    const linkEl = item.querySelector('a.ipc-title-link-wrapper, a[href*="/title/"]');
    const match = linkEl?.href?.match(/tt\d+/);
    return match ? match[0] : null;
  }).filter(Boolean);

  const providerSet = new Set();
  const titleSamples = [];

  for (const id of movies) {
    const variables = JSON.stringify({
      id,
      includeUserPreferredServices: false,
      isProPage: false,
      locale: "en-US",
      location: {
        postalCodeLocation: {
          country: "US",
          postalCode: "95101"
        }
      }
    });
    const extensions = JSON.stringify({
      persistedQuery: {
        sha256Hash: "f15a4004e6e2bed83979a99e9ea57cdb89bd5eee00dacb918bdb2edad67f583c",
        version: 1
      }
    });
    const url = `https://caching.graphql.imdb.com/?operationName=TitleSummaryPromptFromBase&variables=${encodeURIComponent(variables)}&extensions=${encodeURIComponent(extensions)}`;

    try {
      const res = await fetch(url);
      const data = await res.json();
      const cats = data.data?.title?.watchOptionsByCategory?.categorizedWatchOptionsList || [];
      const titleName = data.data?.title?.plot?.plotText?.plainText?.slice(0, 30);
      const provs = [];
      for (const cat of cats) {
        for (const opt of (cat.watchOptions || [])) {
          const name = opt.provider?.name?.value;
          if (name) {
            providerSet.add(name);
            provs.push(`${cat.categoryName?.value}: ${name}`);
          }
        }
      }
      titleSamples.push({ id, provs });
    } catch(e) {}
  }

  return {
    distinctProviders: Array.from(providerSet),
    samples: titleSamples.slice(0, 10)
  };
});

