const watchPaths = await browserjs(tabId, () => {
  const json = JSON.parse(document.getElementById('__NEXT_DATA__').textContent);

  const paths = [];
  const findKey = (obj, p = "") => {
    if (!obj || typeof obj !== 'object') return;
    for (const k of Object.keys(obj)) {
      const cur = p ? `${p}.${k}` : k;
      if (k.toLowerCase().includes('watchoptions')) {
        paths.push({ path: cur, val: obj[k] });
      }
      if (typeof obj[k] === 'object') {
        findKey(obj[k], cur);
      }
    }
  };
  findKey(json);
  return paths.map(x => ({ path: x.path, val: JSON.stringify(x.val).slice(0, 200) }));
});
