const tabId = 118779795;
// Let's see what network requests or data IMDb has on title pages.
// We can navigate to a title page or inspect its HTML.
// But wait, can we fetch the title page via page fetch or inspect?
const result = await browserjs(tabId, async () => {
  const res = await fetch('https://www.imdb.com/title/tt0111161/');
  const text = await res.text();
  // check if "Where to watch" or streaming providers are mentioned in the HTML
  const hasAMC = text.includes('AMC+');
  const hasWatch = text.includes('Where to watch') || text.includes('watch-options') || text.includes('ways-to-watch');
  // let's search for "AMC" or watch provider keywords
  const amcMatches = text.match(/AMC[^\"]{0,50}/g);
  return {
    status: res.status,
    hasAMC,
    hasWatch,
    amcMatches: amcMatches ? amcMatches.slice(0, 5) : null
  };
});
console.log(result);

