const tabId = 118779795;
const watchInfo = await browserjs(tabId, () => {
  const script = document.getElementById('__NEXT_DATA__');
  if (!script) return null;
  const json = JSON.parse(script.textContent);

  // Let's search recursively or check pageProps
  const searchObj = (obj, path = "") => {
    if (!obj || typeof obj !== 'object') return [];
    let matches = [];
    for (const key of Object.keys(obj)) {
      const fullPath = path ? `${path}.${key}` : key;
      if (typeof key === 'string' && (key.toLowerCase().includes('watch') || key.toLowerCase().includes('provider') || key.toLowerCase().includes('stream'))) {
        matches.push({ path: fullPath, val: obj[key] });
      }
      if (typeof obj[key] === 'object') {
        matches = matches.concat(searchObj(obj[key], fullPath));
      }
    }
    return matches;
  };

  const matches = searchObj(json);
  return matches.map(m => ({ path: m.path, type: typeof m.val, preview: JSON.stringify(m.val)?.slice(0, 100) })).slice(0, 20);
});
console.log(watchInfo);

