const tabId = 118779795;
const fetchLog = await browserjs(tabId, async () => {
  window.__capturedFetches = [];
  const originalFetch = window.fetch;
  window.fetch = async function(...args) {
    const url = args[0] ? (typeof args[0] === 'string' ? args[0] : args[0].url) : '';
    const init = args[1] || {};
    try {
      const res = await originalFetch.apply(this, args);
      const clone = res.clone();
      let bodyText = "";
      try {
        bodyText = await clone.text();
      } catch(e) {}
      window.__capturedFetches.push({
        url,
        method: init.method || 'GET',
        body: init.body,
        responsePreview: bodyText.slice(0, 500)
      });
      return res;
    } catch(err) {
      window.__capturedFetches.push({ url, error: err.toString() });
      throw err;
    }
  };
  return "hooked";
});

// Close promptable if open
await browserjs(tabId, () => {
  const closeBtn = document.querySelector('.ipc-promptable-base button[aria-label="Close Prompt"]');
  if (closeBtn) closeBtn.click();
});
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

