await browserjs(tabId, () => {
  const btn = document.querySelector('[data-testid="alternate-button-watch-options-3"]');
  if (btn) btn.click();
});
await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 3000 });

// Check captured fetches
const captured = await browserjs(tabId, () => {
  return window.__capturedFetches;
});
console.log("Captured fetches:", JSON.stringify(captured, null, 2));

