const tabId = 118779795;
// Batch test function
const testBatch = async (startIdx, endIdx) => {
  return await browserjs(tabId, async (start, end) => {
    const items = Array.from(document.querySelectorAll('.ipc-metadata-list-summary-item'));
    const slice = items.slice(start, end).map((item, idx) => {
      const titleEl = item.querySelector('h3, .ipc-title__text');
      const linkEl = item.querySelector('a.ipc-title-link-wrapper, a[href*="/title/"]');
      const match = linkEl?.href?.match(/tt\d+/);
      return {
        rank: start + idx + 1,
        title: titleEl?.textContent?.trim().replace(/^\d+\.\s*/, ''),
        id: match ? match[0] : null,
      };
    }).filter(m => m.id);

    const results = [];

    for (const movie of slice) {
      const variables = JSON.stringify({
        id: movie.id,
        includeUserPreferredServices: false,
        isProPage: false,
        locale: "en-US",
        location: {
          postalCodeLocation: {
            country: "US",
            postalCode: "95101"
          }
        }
      });
      const extensions = JSON.stringify({
        persistedQuery: {
          sha256Hash: "f15a4004e6e2bed83979a99e9ea57cdb89bd5eee00dacb918bdb2edad67f583c",
          version: 1
        }
      });
      const url = `https://caching.graphql.imdb.com/?operationName=TitleSummaryPromptFromBase&variables=${encodeURIComponent(variables)}&extensions=${encodeURIComponent(extensions)}`;

      try {
        const res = await fetch(url);
        const data = await res.json();
        const cats = data.data?.title?.watchOptionsByCategory?.categorizedWatchOptionsList || [];
        const providers = [];
        let hasAmc = false;
        let amcDetails = null;

        for (const cat of cats) {
          const catName = cat.categoryName?.value;
          for (const opt of (cat.watchOptions || [])) {
            const pName = opt.provider?.name?.value;
            const pId = opt.provider?.id;
            providers.push(`${catName}: ${pName}`);
            if (pName?.toLowerCase().includes('amc') || pId?.toLowerCase().includes('amc')) {
              hasAmc = true;
              amcDetails = {
                category: catName,
                providerName: pName,
                providerId: pId,
                title: opt.title?.value,
                description: opt.description?.value,
                link: opt.link
              };
            }
          }
        }

        if (hasAmc) {
          results.push({
            ...movie,
            amcDetails,
            allProviders: providers
          });
        }
      } catch(err) {
        // ignore error
      }
    }

    return results;
  }, startIdx, endIdx);
};

console.log("Checking 0 to 25...");
const r1 = await testBatch(0, 25);
console.log("Batch 0-25 results:", r1);

