const tabId = 118779795;
const scriptGql = await browserjs(tabId, () => {
  // Search scripts for operation names or queries related to watch options
  const scripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent || s.src).filter(Boolean);
  const hits = [];
  for (const s of scripts) {
    if (s.includes('operationName=') || s.includes('watchOptions') || s.includes('waysToWatch')) {
      const matches = s.match(/[a-zA-Z0-9_-]*(?:Watch|Provider|Stream|waysToWatch)[a-zA-Z0-9_-]*/gi);
      if (matches) hits.push(...matches);
    }
  }
  return Array.from(new Set(hits));
});
console.log(scriptGql.slice(0, 30));

