const tabId = 118779795;

const streamingCheck = await browserjs(tabId, async () => {
  const movies = window.__top250.slice(0, 50);
  const streamResults = [];

  for (const m of movies) {
    const variables = JSON.stringify({
      id: m.id,
      includeUserPreferredServices: false,
      isProPage: false,
      locale: "en-US",
      location: {
        postalCodeLocation: {
          country: "US",
          postalCode: "95101"
        }
      }
    });
    const extensions = JSON.stringify({
      persistedQuery: {
        sha256Hash: "f15a4004e6e2bed83979a99e9ea57cdb89bd5eee00dacb918bdb2edad67f583c",
        version: 1
      }
    });
    const url = `https://caching.graphql.imdb.com/?operationName=TitleSummaryPromptFromBase&variables=${encodeURIComponent(variables)}&extensions=${encodeURIComponent(extensions)}`;

    try {
      const res = await fetch(url);
      const data = await res.json();
      const cats = data.data?.title?.watchOptionsByCategory?.categorizedWatchOptionsList || [];
      for (const cat of cats) {
        if (cat.categoryName?.value === 'STREAMING') {
          const provs = (cat.watchOptions || []).map(o => o.provider?.name?.value);
          streamResults.push({
            rank: m.rank,
            title: m.title,
            id: m.id,
            providers: provs
          });
        }
      }
    } catch(e) {}
  }

  return streamResults;
});

console.log("Streaming results for movies 1-50:", streamingCheck);

