const gqlOperations = await browserjs(tabId, () => {
  // Let's find all operationNames mentioned in scripts
  const scripts = Array.from(document.querySelectorAll('script')).map(s => s.textContent || "").filter(Boolean);
  const opNames = new Set();
  const re = /operationName["':\s=]+([a-zA-Z0-9_]+)/g;
  for (const s of scripts) {
    let m;
    while ((m = re.exec(s)) !== null) {
      opNames.add(m[1]);
    }
  }
  return Array.from(opNames);
});
console.log("Found operation names:", gqlOperations);

